let queue=[],index=0,speaking=false;function next(){if(!speaking)return;if(index>=queue.length){speaking=false;$('#audio-status').textContent='讲章朗读完成';return}const u=new SpeechSynthesisUtterance(queue[index++]);u.lang='zh-CN';u.rate=.9;u.onend=next;u.onerror=()=>{if(speaking){speaking=false;$('#audio-status').textContent='朗读中断，请检查设备中文语音。'}};speechSynthesis.speak(u)}$('#speak').onclick=()=>{if(!('speechSynthesis'in window)){$('#audio-status').textContent='此浏览器不支持设备语音。';return}speaking=false;speechSynthesis.cancel();queue=['officers','nicodemus'].flatMap(id=>[...document.querySelectorAll('#'+id+' h2,#'+id+' p')].map(x=>x.textContent));index=0;speaking=true;$('#audio-status').textContent='正在使用设备语音朗读两点讲章';next()};$('#stop').onclick=()=>{speaking=false;if('speechSynthesis'in window)speechSynthesis.cancel();$('#audio-status').textContent='朗读已停止'};addEventListener('pagehide',()=>{speaking=false;if('speechSynthesis'in window)speechSynthesis.cancel()});addEventListener('beforeprint',()=>document.querySelectorAll('.discussion').forEach(x=>{x.dataset.wasOpen=String(x.open);x.open=true}));addEventListener('afterprint',()=>document.querySelectorAll('.discussion').forEach(x=>x.open=x.dataset.wasOpen==='true'));
